// ProjectServiceServer is the server API for ProjectService service.
// All implementations must embed UnimplementedProjectServiceServer
// for forward compatibility.
type ProjectServiceServer interface {
	// Add creates a new Project
	Add(context.Context, *ProjectAddRequest) (*Project, error)
	// Get retrieves a Project
	Get(context.Context, *ProjectGetRequest) (*Project, error)
	// Patch updates an existing Project
	Patch(context.Context, *ProjectPatchRequest) (*Project, error)
	// Apply applies a patch document to an existing Project
	Apply(context.Context, *ProjectApplyRequest) (*Project, error)
	// Erase deletes a Project
	Erase(context.Context, *ProjectRef) (*ProjectEraseResponse, error)
	// List reads Projects a page at a time.
	List(context.Context, *ProjectListRequest) (*ProjectListResponse, error)
	// Watch the Projects this caller may see, as they are now and as they change.
	//
	// What arrives is **state and never a delta**, so a client converges rather
	// than replays: it keeps what it was last told about a row and replaces it.
	// An event it did not receive is one it does not need, since the next one
	// about that row carries the whole of it.
	//
	// The first message is everything that matches right now, so a client does
	// not have to List first and race the subscription. A row may arrive twice --
	// once in that first message and once as a change that happened while it was
	// being read -- and that is harmless for the same reason.
	Watch(*ProjectWatchRequest, grpc.ServerStreamingServer[ProjectWatchResponse]) error
	// Permanently remove one project and its owned data, preserving workspace sources.
	Remove(context.Context, *ProjectRemoveRequest) (*ProjectRemoveReply, error)
	// Ephemeral PTY on the manager host. First frame identifies a project and size;
	// later frames carry input or a resize. Terminal bytes are never journaled.
	Terminal(grpc.BidiStreamingServer[ProjectTerminalRequest, ProjectTerminalReply]) error
	// Ephemeral login transport. First frame identifies the session profile;
	// subsequent frames carry stdin only. These frames are never journaled.
	// Dedicated auxiliary account login; transient and never journaled.
	AuxiliaryLogin(grpc.BidiStreamingServer[ProjectLoginRequest, ProjectLoginOutput]) error
	SessionLogin(grpc.BidiStreamingServer[ProjectLoginRequest, ProjectLoginOutput]) error
	// Read immediate directory entries inside the project's container as its remote user.
	Paths(*ProjectPathsRequest, grpc.ServerStreamingServer[ProjectPathsReply]) error
	// Stream a regular file as the project remote user; never journal file contents.
	Download(*ProjectDownloadRequest, grpc.ServerStreamingServer[ProjectDownloadReply]) error
	// Start/reuse the project's browser editor. The browser gateway removes the
	// private token from RPC replies and scopes its workbench cookie to the proxy.
	Editor(context.Context, *ProjectEditorRequest) (*ProjectEditorReply, error)
	// Private gateway transport to the editor's loopback listener; not web RPC.
	EditorTunnel(grpc.BidiStreamingServer[ProjectEditorTunnelRequest, ProjectEditorTunnelReply]) error
	Devcontainer(context.Context, *DevcontainerRequest) (*DevcontainerReply, error)
	// What one project actually runs under: the configuration cxz handed the
	// devcontainer CLI, every Compose file in merge order, and the merge itself,
	// read back from what provisioning wrote. Devcontainer, above, saves the
	// settings; this reads what a project got from them, which is why the two
	// are not one call.
	RenderDevcontainer(context.Context, *RenderDevcontainerRequest) (*RenderDevcontainerReply, error)
	Docker(context.Context, *DockerRequest) (*DockerReply, error)
	// Aux is a model task done beside a session: run once, with the context cxz
	// assembles, never accumulating into a conversation. These four are the part
	// that belongs to the installation rather than to one session -- which
	// account and model each kind runs on. See docs/plans/aux-api.md.
	AuxConfig(context.Context, *AuxConfigRequest) (*AuxConfigReply, error)
	AuxSetConfig(context.Context, *AuxSetConfigRequest) (*AuxConfigReply, error)
	AuxModels(context.Context, *AuxModelsRequest) (*AuxModelsReply, error)
	AuxLoginInfo(context.Context, *AuxLoginInfoRequest) (*AuxLoginInfoReply, error)
	// Asked by a session supervisor before it compacts a journal, so that a
	// release predating trimming refuses the projection rather than serving
	// history that is gone. A failure stops the compaction.
	MarkHistoryTrimmable(context.Context, *HistoryTrimmableRequest) (*HistoryTrimmableReply, error)
	// The history budgets of this installation. They bound cxz's own records
	// only; provider context is not affected. See docs/history.md.
	GetHistoryPolicy(context.Context, *HistoryPolicyRequest) (*HistoryPolicy, error)
	SetHistoryPolicy(context.Context, *HistoryPolicy) (*HistoryPolicy, error)
	// A secret file is written by the workspace helper inside a project
	// container, for a client that cannot reach the engine itself. Two calls
	// rather than one with a verb: only one of them carries a secret, and that
	// difference is the whole of what has to be obvious here.
	//
	// Whether the link may carry it at all is decided by the client, because the
	// exposed TCP surface is authenticated plaintext and cannot be told apart
	// from a local socket on this side. See internal/transport.Confidential.
	PutSecretFile(context.Context, *PutSecretFileRequest) (*SecretFileReply, error)
	DeleteSecretFile(context.Context, *DeleteSecretFileRequest) (*SecretFileReply, error)
	// The installation's Agent Skills library, and which projects see each
	// skill. One method per decision rather than one with a verb: enabling a
	// skill by default and enabling it for one project write to different
	// places, and restoring a project's default has nowhere to put an on/off
	// that would be ignored. So no request here can name one and mean another.
	GetSkills(context.Context, *SkillsRequest) (*SkillsReply, error)
	AddSkill(context.Context, *SkillRequest) (*SkillsReply, error)
	RemoveSkill(context.Context, *SkillRequest) (*SkillsReply, error)
	SetSkillDefault(context.Context, *SkillDefaultRequest) (*SkillsReply, error)
	SetProjectSkill(context.Context, *ProjectSkillRequest) (*SkillsReply, error)
	ClearProjectSkill(context.Context, *ClearProjectSkillRequest) (*SkillsReply, error)
	// Manager to project container: the skills this project is allowed to see,
	// already resolved. An unactivated skill costs the project nothing, not even
	// the bytes.
	SyncSkills(context.Context, *SyncSkillsRequest) (*SyncSkillsReply, error)
	// MCP registrations, and which projects see each one. The same six decisions
	// as the skills library, for the same reason, plus a definition that arrives
	// whole: its environment and headers hold explicit values, so editing one
	// field at a time would mean reading the others back out first.
	GetMcpServers(context.Context, *McpServersRequest) (*McpServersReply, error)
	PutMcpServer(context.Context, *PutMcpServerRequest) (*McpServersReply, error)
	RemoveMcpServer(context.Context, *McpServerRequest) (*McpServersReply, error)
	SetMcpServerDefault(context.Context, *McpServerDefaultRequest) (*McpServersReply, error)
	SetProjectMcpServer(context.Context, *ProjectMcpServerRequest) (*McpServersReply, error)
	ClearProjectMcpServer(context.Context, *ClearProjectMcpServerRequest) (*McpServersReply, error)
	// What each of a project's live sessions actually launched with, and whether
	// a change is still waiting for a restart. Separate from reading the
	// registrations, because a settings list should not stall on a container.
	McpSessions(context.Context, *McpSessionsRequest) (*McpSessionsReply, error)
	// Manager to project container: the registrations resolved for this project.
	SyncMcpServers(context.Context, *SyncMcpServersRequest) (*SyncMcpServersReply, error)
	FileMappings(context.Context, *FileMappingsRequest) (*FileMappingsReply, error)
	// Provision/start a registered workspace. This never creates a conversation.
	Up(context.Context, *ProjectUpRequest) (*Project, error)
	// Remove owned containers, retaining the resource, workspace and volumes.
	Down(context.Context, *ProjectControl) (*Project, error)
	// Replace only explicitly confirmed targets. Foreign containers are not adopted.
	Recreate(context.Context, *ProjectRecreateRequest) (*Project, error)
	// Foreign inventory is not part of the registered Project resource list.
	InspectForeign(context.Context, *InspectForeignRequest) (*InspectForeignResponse, error)
	mustEmbedUnimplementedProjectServiceServer()
}

